pub trait TPaloBrokerServiceSyncHandler {
  fn handle_list_path(&self, request: TBrokerListPathRequest) -> thrift::Result<TBrokerListResponse>;
  fn handle_list_located_files(&self, request: TBrokerListPathRequest) -> thrift::Result<TBrokerListResponse>;
  fn handle_is_splittable(&self, request: TBrokerIsSplittableRequest) -> thrift::Result<TBrokerIsSplittableResponse>;
  fn handle_delete_path(&self, request: TBrokerDeletePathRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_rename_path(&self, request: TBrokerRenamePathRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_check_path_exist(&self, request: TBrokerCheckPathExistRequest) -> thrift::Result<TBrokerCheckPathExistResponse>;
  fn handle_open_reader(&self, request: TBrokerOpenReaderRequest) -> thrift::Result<TBrokerOpenReaderResponse>;
  fn handle_pread(&self, request: TBrokerPReadRequest) -> thrift::Result<TBrokerReadResponse>;
  fn handle_seek(&self, request: TBrokerSeekRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_close_reader(&self, request: TBrokerCloseReaderRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_open_writer(&self, request: TBrokerOpenWriterRequest) -> thrift::Result<TBrokerOpenWriterResponse>;
  fn handle_pwrite(&self, request: TBrokerPWriteRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_close_writer(&self, request: TBrokerCloseWriterRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_ping(&self, request: TBrokerPingBrokerRequest) -> thrift::Result<TBrokerOperationStatus>;
  fn handle_file_size(&self, request: TBrokerFileSizeRequest) -> thrift::Result<TBrokerFileSizeResponse>;
}

